 { t:"Roots of equations & errors", q:"Applying Newton–Raphson to \\(f(x)=x^{2}-2\\) starting at \\(x_{0}=1\\) gives \\(x_{1}\\) =", o:["2.0","1.414","1.5","1.0"], a:2, e:"\\(x_{1}=1-(-1)/2=1.5\\)." },
 { t:"Roots of equations & errors", q:"The order of convergence of Newton–Raphson for a simple root is:", o:["half","linear","cubic","quadratic (order 2)"], a:3, e:"The error roughly squares at each step." }
