 { t:"Database management (xBase-style commands)", q:"The command REPLACE marks WITH 80 will:", o:["add a new record","print marks","delete the field marks","change the value of the field marks in the current record"], a:3, e:"REPLACE edits field values." },
 { t:"Database programming", q:"STORE 5 TO x:", o:["prints x","creates a table named x","compares x with 5","assigns 5 to the memory variable x"], a:3, e:"Equivalent to \\(x=5\\)." },
 { t:"Database programming", q:"\\(DO\\,\\mathrm{WHILE}\\ldots \\mathrm{ENDDO}\\) is used for:", o:["opening a table","declaring an array","printing a report","repeating a block while a condition is true"], a:3, e:"A loop structure." },
 { t:"Database programming", q:"In xBase, the & symbol is used for:", o:["a logical AND only","macro substitution (treating a string variable’s contents as code or a name)","string length","an array"], a:1, e:"&var is replaced by the contents of the variable var." }
