 { t:"Methods of estimation", q:"The maximum likelihood estimator of \\(\\sigma ^{2}\\) for a normal sample is:", o:["\\((1/n)\\sum x_{i}\\)","\\(\\sum (x_{i}-\\bar{x})^{2}/(n+1)\\)","\\((1/n)\\sum (x_{i}-\\bar{x})^{2}\\)","\\((1/(n-1))\\sum (x_{i}-\\bar{x})^{2}\\)"], a:2, e:"It is biased, with \\(E=(n-1)\\sigma ^{2}/n\\)." },
 { t:"Methods of estimation", q:"In Bayes’ method, the posterior density is proportional to:", o:["prior only","likelihood / prior","prior × likelihood","prior + likelihood"], a:2, e:"\\(\\pi (\\theta |x)\\propto \\pi (\\theta )L(\\theta ;x)\\)." },
 { t:"Methods of estimation", q:"The MLE of the Poisson mean \\(\\lambda\\) from a random sample is:", o:["\\(n/\\sum x_{i}\\)","\\(\\sum x_{i}\\)","\\(\\bar{x}^{2}\\)","x̄"], a:3, e:"\\(\\ln \\,L=-n\\lambda +\\sum x_{i}\\ln \\,\\lambda \\Rightarrow\\) λ̂ \\(=\\bar{x}\\)." },
 { t:"Methods of estimation", q:"The MLE is invariant, which means:", o:["It is always efficient","It is always unbiased","The MLE of \\(g(\\theta )\\) is g(θ̂)","It never changes with n"], a:2, e:"Functional invariance: MLE of \\(g(\\theta )\\) is g of the MLE." },
 { t:"Interval estimation", q:"A 95% CI for \\(\\mu\\) with \\(\\sigma =10\\) known, \\(n=100\\) and \\(\\bar{x}=50\\) is:", o:["(40.2, 59.8)","(48.04, 51.96)","(46.7, 53.3)","(49.0, 51.0)"], a:1, e:"\\(50\\pm 1.96\\times 10/10=50\\pm 1.96\\)." },
 { t:"Interval estimation", q:"The correct interpretation of a 95% confidence interval is:", o:["95% of intervals constructed this way in repeated sampling contain the true parameter","\\(\\mu\\) varies with probability 0.95","95% of the data lie in the interval","there is a 95% probability that \\(\\mu\\) lies in this particular interval"], a:0, e:"The parameter is fixed; the interval is random." },
 { t:"Parametric tests, NP lemma & UMP tests", q:"A uniformly most powerful (UMP) test is a test that:", o:["has the smallest size","has power equal to 1","is unbiased always","is most powerful for every alternative value in a composite alternative"], a:3, e:"UMP tests exist for one-sided alternatives in many families." },
 { t:"Parametric tests, NP lemma & UMP tests", q:"Power of a test equals:", o:["\\(\\beta\\)","\\(1-\\alpha\\)","\\(\\alpha\\)","\\(1-\\beta\\)"], a:3, e:"Power \\(=P\\)(reject \\(H_{0}|H_{1}\\) true) \\(=1-\\beta\\)." },
 { t:"Parametric tests, NP lemma & UMP tests", q:"Type I error is:", o:["Rejecting a true \\(H_{0}\\)","Accepting a false \\(H_{0}\\)","Accepting a true \\(H_{0}\\)","Rejecting a false \\(H_{0}\\)"], a:0, e:"Type I = rejecting \\(H_{0}\\) when it is true; its probability is \\(\\alpha\\)." },
 { t:"Parametric tests, NP lemma & UMP tests", q:"The Neyman–Pearson lemma gives the most powerful test for:", o:["Composite vs composite","Any hypothesis","Simple vs simple hypotheses","Two-sided alternatives"], a:2, e:"It applies to simple \\(H_{0}\\) versus simple \\(H_{1}\\) and uses the likelihood ratio." },
 { t:"Parametric tests, NP lemma & UMP tests", q:"The t-test for one mean with n observations has degrees of freedom:", o:["\\(n-1\\)","n","n+1","\\(n-2\\)"], a:0, e:"One degree of freedom is lost estimating the mean: \\(\\mathrm{df}=n-1\\)." },
 { t:"Parametric tests, NP lemma & UMP tests", q:"If the p-value is 0.03 and \\(\\alpha =0.05\\), we:", o:["Cannot decide","Fail to reject \\(H_{0}\\)","Accept \\(H_{1}\\) with 97% probability","Reject \\(H_{0}\\)"], a:3, e:"\\(p&lt;\\alpha\\), so reject \\(H_{0}\\)." },
 { t:"Non-parametric tests", q:"The sign test for a median uses the number of observations:", o:["ranked","equal to the mean","in the tails of the normal distribution","above (or below) the hypothesised median"], a:3, e:"Under \\(H_{0}\\) the count is Binomial(n, ½)." },
 { t:"Non-parametric tests", q:"The Kruskal–Wallis test is the non-parametric analogue of:", o:["one-way ANOVA","the F test for variances","the \\(\\chi ^{2}\\) test of independence","paired t-test"], a:0, e:"It compares k independent samples using ranks." }
